#include "unity.h"
#include "header.h"
#include "helpers.h"
#include <stdbool.h>

void setUp(void) { }
void tearDown(void) { }

void unit_test_compare_arrival_time_earlier(void) {
    // Setup: create two process nodes with different arrival times
    // Path 2 condition: a->AT != b->AT, so it returns a->AT < b->AT
    // We need a->AT < b->AT to return true

    // Create node a with earlier arrival time
    struct node *a = (struct node *)malloc(sizeof(struct node));
    TEST_ASSERT_NOT_NULL(a);
    a->ID = 1;
    a->AT = 5;    // Earlier arrival time
    a->BT = 10;
    a->priority = 2;
    a->CT = 0;
    a->WT = 0;
    a->TAT = 0;
    a->next = NULL;

    // Create node b with later arrival time
    struct node *b = (struct node *)malloc(sizeof(struct node));
    TEST_ASSERT_NOT_NULL(b);
    b->ID = 2;
    b->AT = 10;   // Later arrival time
    b->BT = 5;
    b->priority = 1;  // Higher priority (lower number) but doesn't matter for this path
    b->CT = 0;
    b->WT = 0;
    b->TAT = 0;
    b->next = NULL;

    // Test: call compare function
    bool result = compare(a, b);

    // Assertions
    // Since a->AT (5) < b->AT (10), result should be true
    TEST_ASSERT_TRUE(result);

    // Also test the opposite case to ensure we're on the right path
    bool reverse_result = compare(b, a);
    TEST_ASSERT_FALSE(reverse_result);

    // Cleanup
    free(a);
    free(b);
}

int test_main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_compare_arrival_time_earlier);
    return UNITY_END();
}

